solution.solution.py:
def squares_of_evens(numbers):
    return [n * n for n in numbers if n % 2 == 0]


def word_lengths(words):
    return {w: len(w) for w in words}


def initials(names):
    return sorted({name[0].upper() for name in names if name})


def transpose(matrix):
    return [[row[i] for row in matrix] for i in range(len(matrix[0]))] if matrix else []


def flatten(lists):
    return [item for inner in lists for item in inner]

unitTests:
import inspect

@test("squares of evens")
def _():
    check_eq(squares_of_evens([1, 2, 3, 4]), [4, 16])
    check_eq(squares_of_evens([-2, 0, 7]), [4, 0])

@test("lengths and initials")
def _():
    check_eq(word_lengths(["fig", "apple"]), {"fig": 3, "apple": 5})
    check_eq(initials(["ada", "Alan", "grace", "", "bob"]), ["A", "B", "G"])

@test("transpose and flatten")
def _():
    check_eq(transpose([[1, 2], [3, 4]]), [[1, 3], [2, 4]])
    check_eq(transpose([[1, 2, 3]]), [[1], [2], [3]])
    check_eq(transpose([]), [])
    check_eq(flatten([[1, 2], [], [3]]), [1, 2, 3])

@test("one return each")
def _():
    for f in (squares_of_evens, word_lengths, initials, transpose, flatten):
        body = [l.strip() for l in inspect.getsource(f).splitlines()[1:] if l.strip()]
        check(len(body) == 1 and body[0].startswith("return "), f"{f.__name__} should be a single return line")

